import React, { useEffect, useState } from 'react';
import { Container, Card, Button, Table, Form, Alert } from 'react-bootstrap';

function StudentDashboard({ user }) {
  const [documents, setDocuments] = useState([]);
  const [selectedFolder, setSelectedFolder] = useState(null);
  const [evaluations, setEvaluations] = useState([]);
  const [grades, setGrades] = useState([]);
  const [news, setNews] = useState([]);
  const [uploadStatus, setUploadStatus] = useState('');

  useEffect(() => {
    // Simular llamadas a API para cargar datos de documentos, evaluaciones, notas y noticias
    setDocuments([
      { folder: 'Presentaciones', files: ['intro.pdf'] },
      { folder: 'Quices', files: ['quiz1.pdf'] },
    ]);

    setEvaluations([
      { name: 'Proyecto 1', uploaded: false, group: true, file: null },
      { name: 'Quiz 1', uploaded: true, file: 'quiz1_respuesta.pdf' },
    ]);

    setGrades([
      { course: 'Matemática', quiz: 80, exam: 90, project: 95 },
    ]);

    setNews([
      { title: 'Bienvenida al curso', date: '2025-05-22', content: 'Empezamos el semestre el lunes.' },
      { title: 'Proyecto 1 asignado', date: '2025-05-20', content: 'Fecha de entrega 30 de mayo.' },
    ]);
  }, []);

  const handleUpload = (e, evalIndex) => {
    const file = e.target.files[0];
    if (file) {
      const updated = [...evaluations];
      updated[evalIndex].uploaded = true;
      updated[evalIndex].file = file.name;
      setEvaluations(updated);
      setUploadStatus(`Archivo "${file.name}" cargado correctamente.`);
    }
  };

  return (
    <Container className="mt-4 text-white">
      <h2>Panel del Estudiante</h2>

      {/* Documentos */}
      <Card className="bg-dark text-white p-3 mb-3">
        <h4>📁 Documentos del Curso</h4>
        {documents.map((doc, index) => (
          <div key={index}>
            <h5 onClick={() => setSelectedFolder(index)} style={{ cursor: 'pointer' }}>{doc.folder}</h5>
            {selectedFolder === index && (
              <ul>
                {doc.files.map((file, i) => (
                  <li key={i}><a href={`#download/${file}`} download>{file}</a></li>
                ))}
              </ul>
            )}
          </div>
        ))}
      </Card>

      {/* Evaluaciones */}
      <Card className="bg-dark text-white p-3 mb-3">
        <h4>📝 Enviar Evaluaciones</h4>
        {uploadStatus && <Alert variant="success">{uploadStatus}</Alert>}
        <Table variant="dark" striped>
          <thead>
            <tr><th>Evaluación</th><th>Estado</th><th>Archivo</th></tr>
          </thead>
          <tbody>
            {evaluations.map((ev, idx) => (
              <tr key={idx}>
                <td>{ev.name} {ev.group && <span>(Grupal)</span>}</td>
                <td>{ev.uploaded ? 'Enviado' : 'Pendiente'}</td>
                <td>
                  {ev.uploaded ? (
                    <a href={`#download/${ev.file}`} download>{ev.file}</a>
                  ) : (
                    <Form.Control type="file" onChange={(e) => handleUpload(e, idx)} />
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </Table>
      </Card>

      {/* Notas */}
      <Card className="bg-dark text-white p-3 mb-3">
        <h4>📊 Reporte de Notas</h4>
        <Table variant="dark" striped>
          <thead>
            <tr><th>Curso</th><th>Quices</th><th>Exámenes</th><th>Proyectos</th></tr>
          </thead>
          <tbody>
            {grades.map((g, idx) => (
              <tr key={idx}>
                <td>{g.course}</td><td>{g.quiz}%</td><td>{g.exam}%</td><td>{g.project}%</td>
              </tr>
            ))}
          </tbody>
        </Table>
      </Card>

      {/* Noticias */}
      <Card className="bg-dark text-white p-3 mb-3">
        <h4>📰 Noticias del Curso</h4>
        {news.sort((a, b) => new Date(b.date) - new Date(a.date)).map((n, i) => (
          <div key={i} className="mb-2">
            <strong>{n.title}</strong> <span className="text-muted">({n.date})</span>
            <p>{n.content}</p>
          </div>
        ))}
      </Card>
    </Container>
  );
}

export default StudentDashboard;
